package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.ruoyi.medical.contracts.*;
import java.time.LocalDateTime;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/** Registers the real distinct SYSTEM_JOB principal, scope, input and initial action atomically.
 * The original successful TASK run is never modified. A queued row is not Temporal acceptance. */
public final class DocumentReviewExecutionService {
    private final JdbcTemplate db;private final DocumentReviewJobService intents;private final RunTokenAuthoritySchema runtime;
    private final TaskSourceVerifierSchema json=new TaskSourceVerifierSchema();
    public static final String MANIFEST=org.apache.commons.codec.digest.DigestUtils.sha256Hex("N07_DOCUMENT_CHECK_EXECUTION_V1");
    public DocumentReviewExecutionService(DataSource data,DocumentReviewJobService intents,RunTokenAuthoritySchema runtime){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.intents=intents;this.runtime=runtime;}
    public record Job(String tenant,String project,String document,String documentRevision,String intent,String run,String principal,
            String step,String action,String operation,String actor,String inputHash,String admissionJson,String baselineJson,
            String scopeId,String ruleId,LocalDateTime created,String classification){}
    Job queued(DocumentReviewAdmission.Verified proof,String intentId)throws Exception {
        proof.requireUnchanged();var a=proof.admission();current(a);WireValues.uuid(intentId);var original=intents.original(a,intentId);var h=proof.document().header();
        for(var e:Map.of("tenant_id",h.tenantId(),"project_id",h.projectId(),"document_id",h.documentId(),"document_revision",h.documentRevision(),"body_sha256",h.bodySha256(),"body_artifact_id",h.bodyArtifactId(),"initiator_id",a.actorId()).entrySet())same(e.getValue(),original.required(e.getKey()).asText());
        var existing=db.query("SELECT run_id FROM document_review_execution WHERE tenant_id=? AND intent_id=? LIMIT 2 FOR UPDATE",(r,n)->r.getString(1),h.tenantId(),intentId);
        if(!existing.isEmpty()){var old=byRun(h.tenantId(),one(existing));var pinned=json.read(old.admissionJson());same(proof.document().baseline(),pinned.required("document_baseline"));same(proof.rules().manifest(),pinned.required("rules_manifest"));same(json.tree(proof.selection()),pinned.required("selection"));return old;}
        String run=id(),principal=id(),step=id(),action=id(),scopeId=id(),ruleId=id(),audit=id(),event=id();var now=now();
        var scope=node().put("schema_version","1.0.0").put("tenant_id",h.tenantId()).put("project_id",h.projectId()).put("initiator_id",a.actorId()).put("run_id",run).put("execution_kind","SYSTEM_JOB");
        scope.set("resources",json.tree(proof.permissions().stream().map(RunTokenAuthoritySchema.Permission::scope).distinct().toList()));runtime.scopeManifest(json.canonical(scope),h.tenantId(),h.projectId(),a.actorId(),run,"SYSTEM_JOB");
        var principalManifest=node().put("schema_version","1.0.0").put("tenant_id",h.tenantId()).put("project_id",h.projectId()).put("initiator_id",a.actorId()).put("run_id",run).put("principal_id",principal).put("scope_sha256",json.hash(scope));
        principalManifest.putArray("services").addObject().put("service_uri",proof.worker().serviceUri()).put("audience",proof.worker().audience());principalManifest.set("permissions",json.tree(proof.permissions()));
        runtime.principalManifest(json.canonical(principalManifest),h.tenantId(),h.projectId(),a.actorId(),run,principal,scope);
        var input=node().put("schema_version","1.0.0").put("execution_kind","SYSTEM_JOB").put("job_type","CHECK_DOCUMENT").put("node_kind","N07").put("tenant_id",h.tenantId()).put("project_id",h.projectId()).put("run_id",run).put("step_id",step).put("intent_id",intentId).put("document_id",h.documentId()).put("document_revision",h.documentRevision()).put("body_sha256",h.bodySha256()).put("baseline_sha256",proof.document().baselineSha256()).put("rules_sha256",proof.rules().sha256());
        input.set("document_body",proof.document().body());input.set("document_baseline",proof.document().baseline());input.set("rules_manifest",proof.rules().manifest());input.set("task_relation",json.tree(Map.of("task_id",h.taskId(),"task_revision",h.taskRevision(),"plan_revision",h.planRevision(),"snapshot_id",h.snapshotId())));
        var admitted=(ObjectNode)proof.evidence();admitted.put("schema_version","1.0.0").put("execution_kind","SYSTEM_JOB").put("job_type","CHECK_DOCUMENT").put("node_kind","N07").put("tenant_id",h.tenantId()).put("project_id",h.projectId()).put("run_id",run).put("step_id",step).put("action_id",action).put("principal_id",principal).put("intent_id",intentId).put("operation_id",original.required("operation_id").asText()).put("actor_id",a.actorId()).put("document_id",h.documentId()).put("document_revision",h.documentRevision()).put("input_sha256",json.hash(input)).put("baseline_sha256",proof.document().baselineSha256()).put("rules_sha256",proof.rules().sha256()).put("scope_manifest_id",scopeId).put("rule_manifest_id",ruleId).put("agent_release_id",proof.selection().agentReleaseId()).put("execution_policy_version",proof.policy().versionId()).put("currency",proof.selection().currency());
        admitted.set("selection",json.tree(proof.selection()));admitted.set("execution_policy",json.tree(proof.selection().executionPolicy()));admitted.set("enterprise_budget",json.tree(proof.enterpriseBudget()));admitted.set("parent_budget",json.tree(proof.parentBudget()));admitted.set("role_version",json.tree(proof.node().roleVersion()));admitted.set("model_version",json.tree(proof.node().modelVersion()));admitted.set("scope_manifest",scope);admitted.set("principal_manifest",principalManifest);admitted.set("input_manifest",input);
        var job=new Job(h.tenantId(),h.projectId(),h.documentId(),h.documentRevision(),intentId,run,principal,step,action,original.required("operation_id").asText(),a.actorId(),json.hash(input),json.canonical(admitted),json.canonical(proof.document().baseline()),scopeId,ruleId,now,h.classification());
        var execution=meta(job,runtime.manifestSha256());execution.putAll(Map.of("run_id",run,"project_id",h.projectId(),"execution_kind","SYSTEM_JOB","scope_manifest",json.canonical(scope)));insert("execution_registry",execution);
        var pr=meta(job,runtime.manifestSha256());pr.putAll(Map.of("principal_id",principal,"project_id",h.projectId(),"initiator_id",a.actorId(),"run_id",run,"capability_manifest",json.canonical(principalManifest),"status","ACTIVE","revision",1,"updated_at",now));insert("run_principal",pr);
        version(job,scopeId,json.hash(scope));version(job,ruleId,proof.rules().sha256());
        var jr=meta(job,runtime.manifestSha256());jr.putAll(Map.of("run_id",run,"project_id",h.projectId(),"execution_kind","SYSTEM_JOB","job_type","CHECK_DOCUMENT","initiator_id",a.actorId(),"input_manifest",json.canonical(input),"config_revision",proof.node().modelVersion().version_id(),"budget_revision",proof.enterpriseBudget().version_id()));
        jr.put("parent_budget_id",one(db.query("SELECT budget_id FROM budget_revision WHERE tenant_id=? AND budget_revision=? LIMIT 2",(r,n)->r.getString(1),h.tenantId(),proof.parentBudget().version_id())));jr.putAll(Map.of("target_kind","DOCUMENT","target_id",h.documentId(),"target_revision",h.documentRevision(),"input_sha256",job.inputHash(),"scope_manifest_id",scopeId,"rule_manifest_id",ruleId,"status","QUEUED","revision",1,"updated_at",now));insert("system_job_run",jr);
        var st=meta(job,runtime.manifestSha256());st.putAll(Map.of("project_id",h.projectId(),"run_id",run,"step_id",step,"role_version",proof.node().roleVersion().version_id(),"input_sha256",job.inputHash(),"status","READY","lease_generation",0,"revision",1,"updated_at",now));insert("run_step",st);
        var ac=meta(job,runtime.manifestSha256());ac.putAll(Map.of("project_id",h.projectId(),"run_id",run,"step_id",step,"action_id",action,"input_sha256",job.inputHash(),"origin_run_id",run,"origin_step_id",step,"origin_action_id",action,"kind","HOST_CONTROL","arguments_sha256",job.inputHash()));ac.putAll(Map.of("tool_version","CHECK_DOCUMENT_HOST_V1","state","BOUND","operation_id",job.operation(),"lease_generation",0,"revision",1,"updated_at",now));insert("step_action_binding",ac);
        var row=meta(job,MANIFEST);row.putAll(Map.of("project_id",job.project(),"run_id",run,"intent_id",intentId,"document_id",job.document(),"document_revision",job.documentRevision(),"operation_id",job.operation(),"admission_json",job.admissionJson(),"admission_sha256",json.hash(admitted),"baseline_json",job.baselineJson(),"input_sha256",job.inputHash()));row.putAll(Map.of("audit_id",audit,"event_id",event));insert("document_review_execution",row);
        var receipt=node().put("schema_version","1.0.0").put("job_type","CHECK_DOCUMENT").put("status","QUEUED").put("run_id",run).put("intent_id",intentId).put("admission_sha256",json.hash(admitted));journal(job,audit,event,"document.check_document.queued",receipt);
        proof.requireUnchanged();return byRun(job.tenant(),run);
    }
    public Job byRun(String tenant,String run)throws Exception {
        if(!TransactionSynchronizationManager.isActualTransactionActive()||!tenant.equals(TenantScope.requireCurrent().tenantId()))deny();
        var row=one(db.queryForList("SELECT * FROM document_review_execution WHERE tenant_id=? AND run_id=? LIMIT 2",tenant,run));var a=json.read(text(row,"admission_json"));same(json.hash(a),text(row,"admission_sha256"));same("SYSTEM_JOB",a.required("execution_kind").asText());same("CHECK_DOCUMENT",a.required("job_type").asText());same("N07",a.required("node_kind").asText());
        var job=new Job(tenant,text(row,"project_id"),text(row,"document_id"),text(row,"document_revision"),text(row,"intent_id"),run,a.required("principal_id").asText(),a.required("step_id").asText(),a.required("action_id").asText(),text(row,"operation_id"),text(row,"created_by"),text(row,"input_sha256"),text(row,"admission_json"),text(row,"baseline_json"),a.required("scope_manifest_id").asText(),a.required("rule_manifest_id").asText(),((java.sql.Timestamp)row.get("created_at")).toLocalDateTime(),text(row,"classification"));
        for(var e:Map.of("tenant_id",job.tenant(),"project_id",job.project(),"run_id",job.run(),"intent_id",job.intent(),"document_id",job.document(),"document_revision",job.documentRevision(),"operation_id",job.operation(),"actor_id",job.actor(),"input_sha256",job.inputHash()).entrySet())same(e.getValue(),a.required(e.getKey()).asText());
        var original=one(db.queryForList("SELECT intent_json,intent_sha256 FROM document_review_intent WHERE tenant_id=? AND intent_id=? AND project_id=? AND operation_id=? AND document_id=? AND document_revision=? AND created_by=? LIMIT 2",tenant,job.intent(),job.project(),job.operation(),job.document(),job.documentRevision(),job.actor()));same(json.hash(json.read(text(original,"intent_json"))),text(original,"intent_sha256"));
        var receipt=node().put("schema_version","1.0.0").put("job_type","CHECK_DOCUMENT").put("status","QUEUED").put("run_id",run).put("intent_id",job.intent()).put("admission_sha256",json.hash(a));
        same(json.canonical(receipt),one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND action='document.check_document.queued' AND request_id=? AND trace_id=? AND result='SUCCESS' LIMIT 2",(r,n)->r.getString(1),tenant,job.project(),text(row,"audit_id"),job.actor(),job.operation(),run)));
        same(json.canonical(receipt),one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND aggregate_revision=1 AND event_type='document.check_document.queued' LIMIT 2",(r,n)->r.getString(1),tenant,text(row,"event_id"),run)));
        same(job.inputHash(),json.hash(a.required("input_manifest")));same(json.read(job.baselineJson()),a.required("document_baseline"));same(MANIFEST,text(row,"schema_manifest_sha256"));same("1.0.0",text(row,"schema_version"));
        if(one(db.query("SELECT COUNT(*) FROM system_job_run WHERE tenant_id=? AND project_id=? AND run_id=? AND execution_kind='SYSTEM_JOB' AND job_type='CHECK_DOCUMENT' AND target_kind='DOCUMENT' AND target_id=? AND target_revision=? AND input_sha256=? AND scope_manifest_id=? AND rule_manifest_id=?",(r,n)->r.getInt(1),tenant,job.project(),run,job.document(),job.documentRevision(),job.inputHash(),job.scopeId(),job.ruleId()))!=1)bad();
        same(json.canonical(a.required("input_manifest")),one(db.query("SELECT input_manifest FROM system_job_run WHERE tenant_id=? AND run_id=?",(r,n)->r.getString(1),tenant,run)));
        return job;
    }
    public JsonNode input(Job job)throws Exception{same(job,byRun(job.tenant(),job.run()));return json.read(job.admissionJson()).required("input_manifest").deepCopy();}
    private void version(Job j,String id,String hash){insert("version_registry",Map.of("tenant_id",j.tenant(),"version_id",id,"owner_project_id",j.project(),"entity_kind","DOCUMENT_CHECK_MANIFEST","content_sha256",hash));}
    private void journal(Job j,String audit,String event,String action,JsonNode receipt)throws Exception{var log=meta(j,MANIFEST);log.putAll(Map.of("project_id",j.project(),"audit_id",audit,"subject_id",j.actor(),"action",action,"resource_ref",json.canonical(receipt),"result","SUCCESS","request_id",j.operation(),"trace_id",j.run()));insert("audit_event",log);insert("outbox_event",Map.of("tenant_id",j.tenant(),"event_id",event,"aggregate_id",j.run(),"aggregate_revision",1,"event_type",action,"payload",json.canonical(receipt),"occurred_at",j.created()));}
    private Map<String,Object> meta(Job j,String manifest){var n=new LinkedHashMap<String,Object>();n.putAll(Map.of("tenant_id",j.tenant(),"schema_version","1.0.0","schema_manifest_sha256",manifest,"created_by",j.actor(),"created_at",j.created(),"classification",j.classification()));return n;}
    private void insert(String table,Map<String,Object> values){var keys=new ArrayList<>(values.keySet());if(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(values::get).toArray())!=1)bad();}
    private LocalDateTime now(){return one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));}private static ObjectNode node(){return com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.objectNode();}private static String id(){return UUID.randomUUID().toString();}private static String text(Map<String,Object> row,String key){var value=row.get(key);if(value==null)bad();return value.toString();}private static <T>T one(List<T> rows){if(rows.size()!=1)bad();return rows.get(0);}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void current(EnterpriseAccess.Admission a){if(!TransactionSynchronizationManager.isActualTransactionActive()||!a.actorId().equals(TenantScope.requireCurrent().subjectId()))deny();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
